{
  "probability": 0.99,
  "range_low": 0.90,
  "range_high": 0.99,
  "summary": [
    "Early 2026 shows an unusually deadly pace, with around 606 Mediterranean deaths/missing by late February, marking the deadliest start to a year on record in the IOM dataset.",
    "If March maintains this pace, reaching or exceeding 900 deaths by end-March is plausible; the trajectory into March–April supports a high likelihood of crossing the threshold before April.",
    "Key uncertainties remain (SAR capacity, possible NGO tallies being higher than IOM) but overall factors tilt toward a high probability of ≥900 deaths before the end of April 2026."
  ],
  "confidence": "high",
  "narrative": "The reference-class data show a record-fast pace through February 2026. With ongoing high departures and risk factors, the March–April window reasonably sustains the momentum toward 900 deaths, though exact timing depends on rescue capacity and reporting.",
  "justification": {
    "anchor": {
      "probability": 0.35,
      "basis": "base rate from the reference class (IOM Missing Migrants Project central Mediterranean deaths) anchored to the reported 606 deaths/missing through February 2026; this serves as the starting point before explicit factor updates."
    },
    "factor_updates": [
      {
        "factor": "Pace of Mediterranean deaths early 2026",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "606 deaths/missing by Feb 24 suggests March could add hundreds more; continued high pace makes 900 by end-March plausible."
      },
      {
        "factor": "Potential undercount or higher tolls per NGO estimates",
        "direction": "up",
        "magnitude": "weak",
        "rationale": "NGO tallies sometimes exceed IOM figures, implying the true toll could be higher than 606 by February."
      },
      {
        "factor": "Policy/SAR constraints affecting rescues",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Ongoing SAR strains or restrictions can elevate fatalities, pushing cumulative deaths higher."
      },
      {
        "factor": "March–April seasonal dynamics and potential surge in crossings",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Seasonal patterns often increase risk and crossing attempts in spring, adding upside risk to the trajectory."
      }
    ],
    "synthesis_rationale": "All factors point to an upward revision from the base anchor; despite some uncertainty about exact counts and potential undercounting, the convergence of a high early-2026 pace, continued crossings, and constrained SAR capacity leads to a calibrated high probability that the 900-death threshold will be reached before April 2026. Calibration recognizes correlation among factors (e.g., pace and seasonal dynamics) and assigns a near-maximum posterior within the 0.90–0.99 range."
  }
}

{
