  "summary": [
    "As of late February 2026, about 606 Mediterranean deaths/missing through two months suggest a high likelihood of reaching or exceeding 900 by end-March if the pace continues.",
    "Early-year surge data from IOM Missing Migrants Project align with a continued risk into March–April, though SAR capacity and weather conditions inject uncertainty.",
    "Under-count risk and potential NGO tallies could push totals higher, supporting a near-100% posterior, though SAR improvements could moderate the pace."
  ],
  "confidence": "high",
  "narrative": "The observed 606 deaths by February 2026 imply a sustained, deadly pace into March. Given the historical tendency for spring crossings and limited countervailing SAR improvements, reaching 900 deaths before April is highly probable, with some uncertainty from reporting gaps and policy constraints.",
  "justification": {
    "anchor": {
      "probability": 0.25,
      "basis": "Base rate anchored to the reference class of Central Mediterranean deaths; early-2026 pace (606 by late February) makes near-term 900 by end-March plausible; anchor 0.25 reflects a modest starting probability before upward updates."
    },
    "factor_updates": [
      {
        "factor": "Pace of Mediterranean deaths early 2026",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "606 deaths/missing by late Feb 2026 implies a high likelihood of reaching 900 by end-March if the pace persists; supports higher posterior probability."
      },
      {
        "factor": "Potential undercount or higher tolls per NGO estimates",
        "direction": "up",
        "magnitude": "weak",
        "rationale": "NGO counts sometimes exceed IOM figures, suggesting true toll could be higher than 606, reinforcing probability."
      },
      {
        "factor": "Policy/SAR constraints affecting rescues",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Stronger SAR capacity or safer routes could reduce fatalities, offsetting some risk; introduces downward pressure on the exact 900-by-March outcome."
